package cn.huankan.collector;
import java.nio.charset.StandardCharsets;import java.net.URI;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class SdmxHistoryTest {
 @Test void actualObservationAndDeleteRemainDistinctFromResponseVintage()throws Exception{String xml="<m:GenericData xmlns:m='urn:message' xmlns:g='urn:generic'><m:Header><m:Prepared>2026-10-10T00:00:00Z</m:Prepared></m:Header><m:DataSet action='Delete' validFromDate='2026-10-10T00:00:00Z'><g:Series><g:Obs><g:ObsDimension value='2026-10-01'/></g:Obs></g:Series></m:DataSet></m:GenericData>";var parsed=SdmxHistory.parse(xml.getBytes(StandardCharsets.UTF_8));assertEquals("Delete",parsed.action());assertEquals(1,parsed.points().size());assertNull(parsed.points().getFirst().value());assertEquals("2026-10-10T00:00:00Z",parsed.prepared());}
 @Test void entityExpansionIsRejected(){assertThrows(Exception.class,()->SdmxHistory.parse("<!DOCTYPE x [<!ENTITY a SYSTEM 'file:///C:/Windows/win.ini'>]><x>&a;</x>".getBytes(StandardCharsets.UTF_8)));}
 @Test void onlyBoundedOfficialHistoryQueryVocabularyIsAllowed(){OfficialHttpClient.validate(URI.create("https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A?startPeriod=2026-10-01&endPeriod=2026-10-09&includeHistory=true&updatedAfter=2026-10-01T00%3A00%3A00Z&format=genericdata"));assertThrows(IllegalArgumentException.class,()->OfficialHttpClient.validate(URI.create("https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A?startPeriod=2026-10-01&includeHistory=true&redirect=http://example.invalid&format=genericdata")));}
}
